// Siri Audio Kommentator System für Billardkrüppel
// 60 dynamische Siri-Sprüche (10 pro Kategorie) direkt lokal als Inline-Audio eingebettet
// Funktioniert 100% offline, ohne Netzwerk-Zugriff und ohne CORS/File-Blockaden!

(function() {
  let commentatorEnabled = true;
  let activeAudio = null;

  const AUDIO_DATA = {"thorsten": ["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"], "daniel": ["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"], "peter": ["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"], "sweep": ["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"], "foul": ["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"], "streak": ["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"]};

  const recentHistory = {};

  // Audio-Freischaltung für iOS/Safari/Chrome User-Gesten beim Klick
  window.prepareSiriCommentator = function() {
    try {
      if (!activeAudio) {
        activeAudio = new Audio();
      }
    } catch (e) {}
  };

  window.playSiriComment = function(rawCategory) {
    if (!commentatorEnabled || !rawCategory) return;

    const str = String(rawCategory).toLowerCase();
    let cat = "";

    if (str.includes("thorsten")) cat = "thorsten";
    else if (str.includes("daniel")) cat = "daniel";
    else if (str.includes("peter")) cat = "peter";
    else if (str.includes("sweep")) cat = "sweep";
    else if (str.includes("foul")) cat = "foul";
    else if (str.includes("streak")) cat = "streak";

    if (!cat) return;

    const list = AUDIO_DATA[cat];
    if (!list || list.length === 0) return;

    if (!recentHistory[cat]) recentHistory[cat] = [];
    let availableIndices = [];
    for (let i = 0; i < list.length; i++) {
      if (!recentHistory[cat].includes(i)) availableIndices.push(i);
    }
    if (availableIndices.length === 0) {
      recentHistory[cat] = [];
      for (let i = 0; i < list.length; i++) availableIndices.push(i);
    }

    const chosenIndex = availableIndices[Math.floor(Math.random() * availableIndices.length)];
    recentHistory[cat].push(chosenIndex);
    if (recentHistory[cat].length > 5) {
      recentHistory[cat].shift();
    }

    const src = list[chosenIndex];

    try {
      if (activeAudio) {
        activeAudio.pause();
        activeAudio = null;
      }
      const audio = new Audio(src);
      activeAudio = audio;
      audio.onended = function() { activeAudio = null; };
      audio.onerror = function(e) { activeAudio = null; };
      const p = audio.play();
      if (p && typeof p.catch === "function") {
        p.catch(function() {});
      }
    } catch (e) {}
  };

  window.toggleSiriCommentator = function(enable) {
    if (typeof enable === "boolean") {
      commentatorEnabled = enable;
    } else {
      commentatorEnabled = !commentatorEnabled;
    }
    return commentatorEnabled;
  };

  window.isSiriCommentatorEnabled = function() {
    return commentatorEnabled;
  };
})();
